INSERT INTO `Locations` VALUES (37, 'GP Home Handicraft', 'At GP home we bring you the experience of culture and stories on ceramics that we have selected from famous ceramic villages all over Vietnam, encapsulate it and bring it back to GP home, In addition to Owning yourself handmade ceramic works from all parts of Vietnam, you will understand more about the 1000-year-old culture formed in our country.', 21.033379, 105.85008, 0.00, 0, '18 P. Luong Van Can, Hanoi Old Quarter, Hoan Kiem District, Hanoi, Vietnam', '+84 96 522 64 65', NULL, 242, 1, 'https://www.tripadvisor.com/Attraction_Review-g293924-d26454028-Reviews-GP_Home_Handicraft-Hanoi.html', 280000.00, 550000.00, 60, 5.000000000000000000000000000000, NULL, 1, '2026-04-04 11:15:28', NULL, '2026-04-04 11:15:28', NULL, 0);
