INSERT INTO `Locations` VALUES (40, 'Ames Studio 2 Nha Chung - Handcrafted Souvenir & Gift', 'Hidden Gem in Hanoi Train Street, Ames Studio is a quiet pause in a place known for its movement. Here, the hum of the tracks gives way to the stillness of crafted thingsâ€”wood shaped by hand, paper pressed with memory, clay molded with care. More than a gift shop, itâ€™s a space to slow down, to notice, and to take with you something honest and handmade.', 21.028797, 105.84951, 0.00, 0, '2 Nha Chung Street, Hang Trong Ward, Hoan Kiem District, Hanoi, Vietnam', '+84 88 812 29 09', NULL, 242, 1, 'https://www.tripadvisor.com/Attraction_Review-g293924-d33239187-Reviews-Ames_Studio_2_Nha_Chung_Handcrafted_Souvenir_Gift-Hanoi.html', 50000.00, 300000.00, 30, 4.900000000000000000000000000000, NULL, 1, '2026-04-04 11:15:28', NULL, '2026-04-04 11:15:28', NULL, 0);
INSERT INTO `Locations` VALUES (41, 'Fine Arts Museum', 'This museum was opened in 1966. Though in need of updating, some interesting artifacts are on display in its three floors organized chronologically.', 21.03064, 105.83706, 30000.00, 0, '66 Nguyen Thai Hoc Street, Dien Bien Ward, Ba Dinh District, Hanoi, Vietnam', '+84 24 3823 3084', NULL, 231, 1, 'https://www.tripadvisor.com/Attraction_Review-g293924-d311048-Reviews-Fine_Arts_Museum_Bao_Tang_My_Thuat-Hanoi.html', 30000.00, 50000.00, 75, 4.300000000000000000000000000000, NULL, 1, '2026-04-04 11:15:28', NULL, '2026-04-04 11:15:28', NULL, 0);
