INSERT INTO `Locations` VALUES (75, 'Viettime Craft', 'Viettime Craft is a souvenir shop at Hanoi Old Quarter with handicraft products made by Vietnamese artisants.', 21.034351, 105.85349, 0.00, 0, '43 Nguyen Hy Quang Street, Cho Dua Ward, Dong Da District, Hanoi, Vietnam', '+84 4 6266 2630', NULL, 237, 4, 'https://www.tripadvisor.com/Attraction_Review-g293924-d9748323-Reviews-Viettime_Craft-Hanoi.html', 320000.00, 580000.00, 80, 4.800000000000000000000000000000, NULL, 1, '2026-04-04 11:18:04', NULL, '2026-04-04 11:18:04', NULL, 0);
INSERT INTO `Locations` VALUES (76, 'The Garden Shopping Center', 'Ä‘á»‹a Ä‘iá»ƒm du lá»‹ch', 21.19257, 105.71498, 0.00, 0, 'The Garden Shopping Mall, Me Tri Street, Nam Tu Liem District, Hanoi, Vietnam', '+84 24 3787 5500', NULL, 259, 4, 'https://www.tripadvisor.com/Attraction_Review-g293924-d14928329-Reviews-The_Garden_Shopping_Center-Hanoi.html', 480000.00, 600000.00, 65, 5.000000000000000000000000000000, NULL, 1, '2026-04-04 11:18:04', NULL, '2026-04-04 11:18:04', NULL, 0);
INSERT INTO `Locations` VALUES (77, 'AEON MALL Ha Dong', 'A must-visit destination right in the strategic traffic area of the Southwest, AEON MALL Ha Dong is the second Japanese shopping center in Hanoi with total area of nearly 10 hectares, accommodating up to 2,100 cars and more than 9,000 motorcycles. As one of the largest shopping centers in Vietnam, AEON MALL Ha Dong proudly presents dynamic mix of around 220 stores.', 20.989864, 105.75141, 0.00, 0, 'Duong Noi Urban Area, Hanoi, Vietnam', '+84 24 3757 6999', NULL, 239, 4, 'https://www.tripadvisor.com/Attraction_Review-g17733187-d19893365-Reviews-AEON_MALL_Ha_Dong-Ha_Dong_Hanoi.html', 130000.00, 470000.00, 35, 4.000000000000000000000000000000, NULL, 1, '2026-04-04 11:18:04', NULL, '2026-04-04 11:18:04', NULL, 0);
INSERT INTO `Locations` VALUES (78, 'TiredCity', 'Established in 2016, TiredCity is a chain of gift stores across Vietnam, with 100% of our products developed in collaboration with local artists and partners, each one telling a story deeply rooted in Vietnamese culture and people. At TiredCity, 10% of every purchase goes directly to the artist behind the design, as a meaningful way to support local creative community.', 21.033852, 105.853745, 0.00, 0, '8 Hang Bac Street, Hanoi Old Quarter, Hoan Kiem District, Hanoi, Vietnam', '+84 869 021 661', NULL, 242, 4, 'https://www.tripadvisor.com/Attraction_Review-g293924-d25054361-Reviews-TiredCity_08_Hang_B_c-Hanoi.html', 770000.00, 940000.00, 120, 5.000000000000000000000000000000, NULL, 1, '2026-04-04 11:18:04', NULL, '2026-04-04 11:18:04', NULL, 0);
